# Check the extension conditions exactly as written in Algorithms 1 and 2.
subjects={'A','B'}
items={'x','y'}
edges={(u,v) for u in subjects for v in items}
train={('A','x')}
test={('B','y')}
u_test={'B'}
v_test={'y'}
eeg_train=train.copy()
for u in subjects:
    for v in items:
        if (u,v) in edges and (u,v) not in eeg_train and u not in u_test:
            eeg_train.add((u,v))
fmri_train=train.copy()
for v in items:
    for u in subjects:
        if (u,v) in edges and (u,v) not in fmri_train and v not in v_test:
            fmri_train.add((u,v))
print('Algorithm 1, line 15: initial train/test are disjoint, but extended training stimuli overlap test:',{v for u,v in eeg_train}&v_test)
print('Algorithm 2, line 33: initial train/test are disjoint, but extended training subjects overlap test:',{u for u,v in fmri_train}&u_test)
p,r,f=63.16,71.50,84.64
print('Table 3 UniCoRN 80+(c), P/R/F:',p,r,f)
